class Transfer extends DataClass implements Insertable<Transfer> {
  final int id;
  final int fromAccountId;
  final int toAccountId;

  /// Minor units in fromAccount's currency.
  final int fromAmount;

  /// Minor units in toAccount's currency. UI auto-fills this equal to
  /// fromAmount (converted 1:1) when both accounts share a currency, but it
  /// stays independently editable (e.g. to record a transfer fee), and must
  /// be entered manually when currencies differ. The effective rate is
  /// derived on read (toAmount/toScale ÷ fromAmount/fromScale), never stored.
  final int toAmount;
  final String? note;
  final DateTime date;
  final DateTime createdAt;
  const Transfer({
    required this.id,
    required this.fromAccountId,
    required this.toAccountId,
    required this.fromAmount,
    required this.toAmount,
    this.note,
    required this.date,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['from_account_id'] = Variable<int>(fromAccountId);
    map['to_account_id'] = Variable<int>(toAccountId);
    map['from_amount'] = Variable<int>(fromAmount);
    map['to_amount'] = Variable<int>(toAmount);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    map['date'] = Variable<DateTime>(date);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  TransfersCompanion toCompanion(bool nullToAbsent) {
    return TransfersCompanion(
      id: Value(id),
      fromAccountId: Value(fromAccountId),
      toAccountId: Value(toAccountId),
      fromAmount: Value(fromAmount),
      toAmount: Value(toAmount),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
      date: Value(date),
      createdAt: Value(createdAt),
    );
  }

  factory Transfer.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Transfer(
      id: serializer.fromJson<int>(json['id']),
      fromAccountId: serializer.fromJson<int>(json['fromAccountId']),
      toAccountId: serializer.fromJson<int>(json['toAccountId']),
      fromAmount: serializer.fromJson<int>(json['fromAmount']),
      toAmount: serializer.fromJson<int>(json['toAmount']),
      note: serializer.fromJson<String?>(json['note']),
      date: serializer.fromJson<DateTime>(json['date']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'fromAccountId': serializer.toJson<int>(fromAccountId),
      'toAccountId': serializer.toJson<int>(toAccountId),
      'fromAmount': serializer.toJson<int>(fromAmount),
      'toAmount': serializer.toJson<int>(toAmount),
      'note': serializer.toJson<String?>(note),
      'date': serializer.toJson<DateTime>(date),
      'createdAt': serializer.toJson<DateTime>(createdAt),
    };
  }

  Transfer copyWith({
    int? id,
    int? fromAccountId,
    int? toAccountId,
    int? fromAmount,
    int? toAmount,
    Value<String?> note = const Value.absent(),
    DateTime? date,
    DateTime? createdAt,
  }) => Transfer(
    id: id ?? this.id,
    fromAccountId: fromAccountId ?? this.fromAccountId,
    toAccountId: toAccountId ?? this.toAccountId,
    fromAmount: fromAmount ?? this.fromAmount,
    toAmount: toAmount ?? this.toAmount,
    note: note.present ? note.value : this.note,
    date: date ?? this.date,
    createdAt: createdAt ?? this.createdAt,
  );
  Transfer copyWithCompanion(TransfersCompanion data) {
    return Transfer(
      id: data.id.present ? data.id.value : this.id,
      fromAccountId: data.fromAccountId.present
          ? data.fromAccountId.value
          : this.fromAccountId,
      toAccountId: data.toAccountId.present
          ? data.toAccountId.value
          : this.toAccountId,
      fromAmount: data.fromAmount.present
          ? data.fromAmount.value
          : this.fromAmount,
      toAmount: data.toAmount.present ? data.toAmount.value : this.toAmount,
      note: data.note.present ? data.note.value : this.note,
      date: data.date.present ? data.date.value : this.date,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Transfer(')
          ..write('id: $id, ')
          ..write('fromAccountId: $fromAccountId, ')
          ..write('toAccountId: $toAccountId, ')
          ..write('fromAmount: $fromAmount, ')
          ..write('toAmount: $toAmount, ')
          ..write('note: $note, ')
          ..write('date: $date, ')
          ..write('createdAt: $createdAt')
